import type { Metadata } from "next";
import { company } from "@/content/company";
import { getArticles, getDictionary, getProducts, hasDictionary, type Article, type Product } from "@/content/index";
import { LOCALE_META, LOCALES, type Locale } from "@/i18n/config";
import { siteUrl } from "@/lib/site-url";
import { articleHref, href, languageAlternates, productHref, type RouteKey } from "@/i18n/routes";

type OpenGraph = NonNullable<Metadata["openGraph"]>;
type PageKey = keyof ReturnType<typeof getDictionary>["meta"]["pages"];

/** Link-preview card generated by `npm run assets` (scripts/prepare-brand-assets.mjs). */
export const SOCIAL_CARD = { url: "/images/og-card.png", width: 1200, height: 630, alt: company.name };

/** Open Graph fields shared by every page; a page's own openGraph replaces the parent's, so each carries these. */
export function baseOpenGraph(locale: Locale): OpenGraph {
  return { type: "website", locale: LOCALE_META[locale].ogLocale, siteName: company.name, images: [SOCIAL_CARD] };
}

function buildMetadata(locale: Locale, title: string, description: string, path: string, alternates: Partial<Record<Locale, string>>): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path, languages: languageAlternates(alternates) },
    openGraph: { ...baseOpenGraph(locale), title, description, url: path },
  };
}

/** Metadata for a static page: title/description from the dictionary, URLs from the route map. */
export function pageMetadata(page: PageKey & RouteKey, locale: Locale): Metadata {
  const { title, description } = getDictionary(locale).meta.pages[page];
  const alternates = Object.fromEntries(LOCALES.map((each) => [each, href(page, each)]));
  return buildMetadata(locale, title, description, href(page, locale), alternates);
}

export function productMetadata(product: Product, locale: Locale): Metadata {
  const alternates: Partial<Record<Locale, string>> = {};
  for (const each of LOCALES.filter(hasDictionary)) {
    const translated = getProducts(each).find((candidate) => candidate.id === product.id);
    if (translated) alternates[each] = productHref(translated.slug, each);
  }
  return buildMetadata(locale, product.name, product.summary, productHref(product.slug, locale), alternates);
}

export function articleMetadata(article: Article, locale: Locale): Metadata {
  const alternates: Partial<Record<Locale, string>> = {};
  for (const each of LOCALES.filter(hasDictionary)) {
    const translated = getArticles(each).find((candidate) => candidate.id === article.id);
    if (translated) alternates[each] = articleHref(translated.slug, each);
  }
  return buildMetadata(locale, article.title, article.excerpt, articleHref(article.slug, locale), alternates);
}

export function organizationJsonLd() {
  const { contact, legal } = company;
  return {
    "@context": "https://schema.org",
    "@type": "Organization",
    name: company.name,
    legalName: legal.company,
    url: siteUrl,
    logo: `${siteUrl}/images/logo.png`,
    foundingDate: String(company.foundedYear),
    email: contact.email,
    telephone: contact.phones[0],
    address: {
      "@type": "PostalAddress",
      streetAddress: contact.address.street,
      addressLocality: contact.address.district,
      addressRegion: contact.address.province,
      addressCountry: contact.address.country,
    },
  };
}

export function productJsonLd(product: Product, locale: Locale) {
  return {
    "@context": "https://schema.org",
    "@type": "Product",
    name: `${company.name} ${product.name}`,
    description: product.summary,
    brand: { "@type": "Brand", name: company.name },
    url: `${siteUrl}${productHref(product.slug, locale)}`,
  };
}
